<h1><?= te('Employment paperwork · I-9 and W-4') ?></h1><p class="sub"><?= te('Track completed official forms and the employer\'s verification. This workflow stores evidence and review records; it does not replace the official forms or an electronic I-9 provider.') ?></p><div class="card"><a href="https://www.uscis.gov/i-9" target="_blank" rel="noopener"><?= te('Official I-9 form and instructions') ?></a> · <a href="https://www.irs.gov/forms-pubs/about-form-w-4" target="_blank" rel="noopener"><?= te('Official W-4 form') ?></a> · <a href="/proofs"><?= te('Upload completed form evidence') ?></a></div>
<?php if(!$isWorker): ?><form class="card row" method="get"><select name="candidate_id"><?php foreach($candidates as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Open employment record') ?></button></form><?php endif; ?>
<?php if($case): ?><div class="card"><h2><?= e($case['full_name']) ?></h2><p>I-9: <b><?= e($case['i9_status']) ?></b> · W-4: <b><?= e($case['w4_status']) ?></b></p><p>First day: <?= e($case['first_day']) ?> · Review due: <?= e($case['review_due_on']) ?> · Verifier: <?= e($case['verifier_name']) ?></p></div>
<?php if($isWorker): ?><div class="grid g2"><?php foreach(['section1'=>'I-9 Section 1','w4'=>'W-4'] as $action=>$label): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="<?= e($action) ?>"><h2><?= e($label) ?></h2><label><?= te('Uploaded completed form') ?></label><select name="document_id"><?php foreach($documents as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['document_type'].' · '.$d['status']) ?></option><?php endforeach; ?></select><label><input style="width:auto" type="checkbox" name="attest" required> <?= te('I completed and signed the official form identified above.') ?></label><button class="btn"><?= te('Submit form for review') ?></button></form><?php endforeach; ?></div>
<?php else: ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="employer"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><h2><?= te('Record completed employer verification') ?></h2><label><?= te('Completed employer-signed I-9 evidence') ?></label><select name="document_id"><?php foreach($documents as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['document_type'].' · '.$d['status']) ?></option><?php endforeach; ?></select><label><?= te('Authorized verifier\'s name') ?></label><input name="verifier_name" required maxlength="190"><label><?= te('Verification performed by') ?></label><select name="verification_method"><option value="in_person"><?= te('Employer in person') ?></option><option value="authorized_representative"><?= te('Authorized representative in person') ?></option></select><div class="row"><div><label><?= te('First day of employment') ?></label><input type="date" name="first_day" required></div><div><label><?= te('Employer review deadline · set from applicable business calendar') ?></label><input type="date" name="review_due_on" required></div></div><label><input type="checkbox" style="width:auto" name="attest" required><?= te('The authorized verifier examined the required original documents and completed and signed the employer section of the official I-9.') ?></label><button class="btn"><?= te('Record employer completion') ?></button></form><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review_w4"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><h2><?= te('W-4 review') ?></h2><p><?= te('Review the submitted form and forward it through the approved payroll process.') ?></p><button class="btn"><?= te('Mark W-4 reviewed') ?></button></form><?php endif; endif; ?>